import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC02%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E6%8A%80%E6%9C%AF%E5%8F%91%E5%B1%95/","title":"第02章 信息技术发展","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第02章 信息技术发展/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="第02章-信息技术发展" tabindex="-1"><a class="header-anchor" href="#第02章-信息技术发展"><span>第02章 信息技术发展</span></a></h1><h2 id="本章概览" tabindex="-1"><a class="header-anchor" href="#本章概览"><span>本章概览</span></a></h2><p>本章介绍信息技术的发展历程、新技术趋势以及信息化标准规范。</p><p><strong>重点知识点：</strong></p><ul><li>信息技术发展历程</li><li>新技术（云计算、大数据、人工智能）</li><li>信息化标准体系</li><li>信息安全技术</li></ul><hr><h2 id="_2-1-信息技术概述" tabindex="-1"><a class="header-anchor" href="#_2-1-信息技术概述"><span>2.1 信息技术概述</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>信息技术是指用于管理和处理信息所采用的各种技术的总称。</p><h3 id="发展阶段" tabindex="-1"><a class="header-anchor" href="#发展阶段"><span>发展阶段</span></a></h3><ol><li><strong>第一代</strong>：电子管计算机</li><li><strong>第二代</strong>：晶体管计算机</li><li><strong>第三代</strong>：集成电路计算机</li><li><strong>第四代</strong>：大规模集成电路计算机</li><li><strong>第五代</strong>：人工智能计算机</li></ol><h3 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h3><ul><li>信息技术发展的五个阶段</li><li>各阶段的主要特征</li></ul><h3 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h3><p>电子管，晶体管，集成大集人工智能</p><hr><h2 id="_2-2-新技术发展" tabindex="-1"><a class="header-anchor" href="#_2-2-新技术发展"><span>2.2 新技术发展</span></a></h2><h3 id="云计算" tabindex="-1"><a class="header-anchor" href="#云计算"><span>云计算</span></a></h3><ul><li>定义：基于互联网的计算方式</li><li>服务模式：IaaS、PaaS、SaaS</li><li>特点：按需服务、弹性扩展</li></ul><h3 id="大数据" tabindex="-1"><a class="header-anchor" href="#大数据"><span>大数据</span></a></h3><ul><li>定义：海量、高速、多样的数据集合</li><li>特征：Volume、Velocity、Variety、Value、Veracity</li><li>应用：数据挖掘、预测分析</li></ul><h3 id="人工智能" tabindex="-1"><a class="header-anchor" href="#人工智能"><span>人工智能</span></a></h3><ul><li>定义：使计算机模拟人类智能的技术</li><li>应用：机器学习、自然语言处理、计算机视觉</li></ul><h3 id="关键考点-1" tabindex="-1"><a class="header-anchor" href="#关键考点-1"><span>关键考点</span></a></h3><ul><li>云计算三种服务模式的区别</li><li>大数据的5V特征</li><li>AI的主要应用领域</li></ul><h3 id="记忆口诀-1" tabindex="-1"><a class="header-anchor" href="#记忆口诀-1"><span>记忆口诀</span></a></h3><p>云大物移智，新技促升级</p><hr><h2 id="_2-3-信息化标准" tabindex="-1"><a class="header-anchor" href="#_2-3-信息化标准"><span>2.3 信息化标准</span></a></h2><h3 id="标准化的意义" tabindex="-1"><a class="header-anchor" href="#标准化的意义"><span>标准化的意义</span></a></h3><ul><li>确保系统互操作性</li><li>提高系统可靠性</li><li>降低开发成本</li></ul><h3 id="主要标准" tabindex="-1"><a class="header-anchor" href="#主要标准"><span>主要标准</span></a></h3><ul><li>ISO/IEC 27001：信息安全管理</li><li>IEEE 802：网络标准</li><li>SQL标准：数据库语言</li></ul><h3 id="关键考点-2" tabindex="-1"><a class="header-anchor" href="#关键考点-2"><span>关键考点</span></a></h3><ul><li>信息化标准的作用</li><li>常见的国际标准</li></ul><h3 id="记忆口诀-2" tabindex="-1"><a class="header-anchor" href="#记忆口诀-2"><span>记忆口诀</span></a></h3><p>标准规范保质量，互操作降成本</p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};